import{_ as i,c as n,o as t,a2 as r}from"./chunks/framework.CIiVzG-O.js";const c=JSON.parse('{"title":"Fehlerbehebung","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/troubleshooting.md","filePath":"de/guide/troubleshooting.md","lastUpdated":1793163976000}'),a={name:"de/guide/troubleshooting.md"};function s(l,e,o,h,d,u){return t(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="fehlerbehebung" tabindex="-1">Fehlerbehebung <a class="header-anchor" href="#fehlerbehebung" aria-label="Permalink to &quot;Fehlerbehebung&quot;">​</a></h1><p>Diese Seite sammelt häufige Probleme mit NueZip unter macOS und deren Lösung.</p><h2 id="anwendung-startet-nicht-oder-sturzt-beim-start-ab" tabindex="-1">Anwendung startet nicht oder stürzt beim Start ab <a class="header-anchor" href="#anwendung-startet-nicht-oder-sturzt-beim-start-ab" aria-label="Permalink to &quot;Anwendung startet nicht oder stürzt beim Start ab&quot;">​</a></h2><p>Symptome: NueZip öffnet nicht, stürzt sofort ab oder zeigt einen unerwarteten Fehler an.</p><p>Schritte zur Lösung:</p><ol><li>Stellen Sie sicher, dass Ihre macOS-Version die Mindestanforderungen erfüllt (macOS 14 Sonoma+).</li><li>Beenden Sie die App und starten Sie sie neu.</li><li>Starten Sie Ihren Mac neu.</li><li>Wenn die App von GitHub Releases heruntergeladen wurde, versuchen Sie, das neueste Build oder die notarisierte Version herunterzuladen.</li><li>Wenn die Probleme bestehen bleiben, sammeln Sie Protokolle (siehe unten) und öffnen Sie ein Issue.</li></ol><h2 id="ein-rar-archiv-kann-nicht-geoffnet-werden" tabindex="-1">Ein RAR-Archiv kann nicht geöffnet werden <a class="header-anchor" href="#ein-rar-archiv-kann-nicht-geoffnet-werden" aria-label="Permalink to &quot;Ein RAR-Archiv kann nicht geöffnet werden&quot;">​</a></h2><p>Symptome: NueZip kann eine <code>.rar</code>-Datei nicht öffnen oder zeigt einen Fehler an.</p><p>Checkliste:</p><ol><li>Stellen Sie sicher, dass die RAR-Datei nicht beschädigt ist. Versuchen Sie, sie mit einem anderen Werkzeug wie The Unarchiver zu öffnen.</li><li>Multi-Volume-RAR-Archive müssen alle Teile enthalten (<code>.part1.rar</code>, <code>.part2.rar</code> usw.).</li><li>Passwortgeschützte RAR-Archive benötigen das korrekte Passwort.</li><li>Das RAR5-Format wird unterstützt. Wenn Sie ein älteres RAR-Format haben, melden Sie es bitte.</li></ol><h2 id="extraktion-schlagt-mit-passwortfehler-fehl" tabindex="-1">Extraktion schlägt mit Passwortfehler fehl <a class="header-anchor" href="#extraktion-schlagt-mit-passwortfehler-fehl" aria-label="Permalink to &quot;Extraktion schlägt mit Passwortfehler fehl&quot;">​</a></h2><p>Symptome: Extraktion schlägt fehl mit „Falsches Passwort&quot; oder Entschlüsselungsfehler.</p><p>Checkliste:</p><ol><li>Verifizieren Sie, dass das Passwort korrekt ist — Passwörter sind groß-/kleinschreibungssensitiv.</li><li>Stellen Sie sicher, dass der korrekte Verschlüsselungstyp unterstützt wird (AES-256 für ZIP).</li><li>Versuchen Sie, das Passwort erneut aus dem Passwort-Manager einzugeben.</li></ol><h2 id="finder-erweiterung-wird-nicht-angezeigt" tabindex="-1">Finder-Erweiterung wird nicht angezeigt <a class="header-anchor" href="#finder-erweiterung-wird-nicht-angezeigt" aria-label="Permalink to &quot;Finder-Erweiterung wird nicht angezeigt&quot;">​</a></h2><p>Symptome: Das Rechtsklicken auf ein Archiv im Finder zeigt keine NueZip-Optionen.</p><p>Checkliste:</p><ol><li>Aktivieren Sie die Erweiterung: Systemeinstellungen → Datenschutz &amp; Sicherheit → Erweiterungen → Finder-Erweiterungen → <strong>NueZip</strong> aktivieren.</li><li>Starten Sie den Finder neu: Klicken Sie im Aktivitätsmonitor mit der rechten Maustaste auf Finder → Relaunch, oder führen Sie <code>killall Finder</code> im Terminal aus.</li><li>Installieren Sie die App neu, falls die Erweiterung weiterhin nicht erscheint.</li></ol><h2 id="lizenz-kauf-wird-nicht-angezeigt" tabindex="-1">Lizenz / Kauf wird nicht angezeigt <a class="header-anchor" href="#lizenz-kauf-wird-nicht-angezeigt" aria-label="Permalink to &quot;Lizenz / Kauf wird nicht angezeigt&quot;">​</a></h2><p>Symptome: Sie haben NueZip gekauft, aber es wird weiterhin als Testversion angezeigt.</p><p>Checkliste:</p><ol><li>Stellen Sie sicher, dass Sie mit derselben Apple ID angemeldet sind, die für den Kauf verwendet wurde.</li><li>Stellen Sie Käufe wieder her: NueZip → Einstellungen → Lizenz → Käufe wiederherstellen.</li><li>Kontaktieren Sie den Support, wenn das Problem bestehen bleibt.</li></ol><h2 id="debug-protokolle-sammeln" tabindex="-1">Debug-Protokolle sammeln <a class="header-anchor" href="#debug-protokolle-sammeln" aria-label="Permalink to &quot;Debug-Protokolle sammeln&quot;">​</a></h2><p>Um bei der Diagnose von Problemen zu helfen, sammeln Sie Debug-Protokolle aus NueZip:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Protokolle zur Freigabe auf den Desktop kopieren</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nuezip/Data/Library/Logs/NueZip/nuezip.log</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Desktop/NueZip-Logs</span></span></code></pre></div><p>Öffnen Sie dann ein Issue auf <a href="https://github.com/nuezip/nuezip/issues" target="_blank" rel="noreferrer">GitHub Issues</a> und hängen Sie die Protokolle an.</p><h2 id="berechtigungsbezogene-probleme" tabindex="-1">Berechtigungsbezogene Probleme <a class="header-anchor" href="#berechtigungsbezogene-probleme" aria-label="Permalink to &quot;Berechtigungsbezogene Probleme&quot;">​</a></h2><p>Wenn eine Funktion nach dem Gewähren der Berechtigung dennoch nicht funktioniert:</p><ol><li>Beenden Sie die App und öffnen Sie sie erneut, nachdem Sie die Berechtigung gewährt haben.</li><li>Setzen Sie die Berechtigungsabfrage bei Bedarf mit <code>tccutil</code> zurück (siehe die <a href="./permissions.html">Berechtigungsanleitung</a>).</li></ol><h2 id="leistungsprobleme" tabindex="-1">Leistungsprobleme <a class="header-anchor" href="#leistungsprobleme" aria-label="Permalink to &quot;Leistungsprobleme&quot;">​</a></h2><p>Wenn die App langsam ist oder nicht reagiert:</p><ol><li>Schließen Sie andere ressourcenintensive Anwendungen.</li><li>Versuchen Sie, ein kleineres Archiv zu extrahieren, um das Problem zu isolieren.</li><li>Starten Sie die App neu, wenn die Leistung über die Zeit abnimmt.</li></ol><h2 id="protokolle-anzeigen" tabindex="-1">Protokolle anzeigen <a class="header-anchor" href="#protokolle-anzeigen" aria-label="Permalink to &quot;Protokolle anzeigen&quot;">​</a></h2><p>Zur Fehlerbehebung bei Abstürzen oder Problemen sind Anwendungsprotokolle das nützlichste Artefakt. Bei sandboxed (App Store)-Builds prüfen Sie:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.nuezip/Data/Library/Logs/NueZip/nuezip.log</span></span></code></pre></div><h2 id="app-zurucksetzen" tabindex="-1">App zurücksetzen <a class="header-anchor" href="#app-zurucksetzen" aria-label="Permalink to &quot;App zurücksetzen&quot;">​</a></h2><p>So setzen Sie Einstellungen zurück und löschen lokale Daten:</p><ol><li>Beenden Sie NueZip</li><li>Entfernen Sie den Container (Vorsicht — dies löscht alle Einstellungen):</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nuezip</span></span></code></pre></div><ol start="3"><li>Öffnen Sie NueZip erneut und konfigurieren Sie es neu.</li></ol><h2 id="ein-problem-melden" tabindex="-1">Ein Problem melden <a class="header-anchor" href="#ein-problem-melden" aria-label="Permalink to &quot;Ein Problem melden&quot;">​</a></h2><p>Geben Sie beim Öffnen eines Issues an:</p><ul><li>macOS-Version (Apple-Menü → Über diesen Mac)</li><li>NueZip-Version (NueZip → Über)</li><li>Schritte zur Reproduktion</li><li>Protokolle (siehe Abschnitt <a href="#view-logs">Protokolle anzeigen</a> zur Vorgehensweise)</li></ul><p>Dies hilft den Maintern, das Problem schneller zu identifizieren und zu beheben.</p>`,44)])])}const g=i(a,[["render",s]]);export{c as __pageData,g as default};
